-- The dev account. `public.handle_new_dj`'s on_auth_user_created trigger
-- creates the matching `public.djs` row, so this insert is the only identity
-- write needed. `crypt`/`gen_salt` come from pgcrypto, which the auth schema
-- already installs.
-- The six token columns are EMPTY STRINGS, not NULL, and that is not
-- cosmetic: GoTrue scans them into non-nullable Go strings, so a NULL makes
-- every sign-in fail with `500 Database error querying schema` and
-- `converting NULL to string is unsupported` — which looks like bad
-- credentials from the browser and is not. Verified against the local stack.
insert into auth.users (
  instance_id, id, aud, role, email, encrypted_password, email_confirmed_at,
  created_at, updated_at, raw_app_meta_data, raw_user_meta_data,
  confirmation_token, recovery_token, email_change_token_new, email_change,
  email_change_token_current, reauthentication_token
) values (
  '00000000-0000-0000-0000-000000000000',
  '00000000-0000-4000-8000-00000000d15c',
  'authenticated', 'authenticated',
  'dev@curfew.local',
  crypt('curfew-dev-password', gen_salt('bf')),
  now(), now(), now(),
  '{"provider":"email","providers":["email"]}'::jsonb, '{}'::jsonb,
  '', '', '', '', '', ''
) on conflict (id) do nothing;

-- Password sign-in needs the matching identity row; without it the account
-- exists but `signInWithPassword` reports invalid credentials.
insert into auth.identities (
  provider_id, user_id, identity_data, provider, last_sign_in_at, created_at, updated_at
) values (
  '00000000-0000-4000-8000-00000000d15c', '00000000-0000-4000-8000-00000000d15c',
  jsonb_build_object('sub', '00000000-0000-4000-8000-00000000d15c', 'email', 'dev@curfew.local', 'email_verified', true),
  'email', now(), now(), now()
) on conflict (provider, provider_id) do nothing;

